import Image from "next/image"
import React from "react"

const CustomImage = ({
  imageSrc,
  width,
  height,
  alt,
  className,
}) => {
  return (
    <Image
      src={imageSrc}
      width={width}
      height={height}
      alt={alt ? "" : "not found"}
      className={className}
    />
  )
}

export default CustomImage
