"use client"
import { useState, Fragment } from "react"
import { Dialog, DialogPanel, Transition, DialogBackdrop, DialogTitle, Description } from "@headlessui/react"
import CustomImage from "@/components/molecules/customImage"
import { cn } from "@/lib/utils"

const DialogBox = ({
  title,
  description,
  showCloseIcon,
  children,
  dialogBoxStyle,
  titleStyle,
  dialogBodyStyle,
}) => {
  const [isOpen, setIsOpen] = useState(false)

  return (
    <>
      <button onClick={() => setIsOpen(true)}>Open dialog</button>

      <Transition show={isOpen} as={Fragment}>
        <Dialog onClose={() => setIsOpen(false)} className="relative z-50">

          {/* Overlay */}
          <DialogBackdrop className="fixed inset-0 bg-black/40" />

          {/* Container */}
          <div className="fixed inset-0 flex w-screen items-center justify-center lg:p-4">

            {/* PANEL WITH ANIMATION */}
            <Transition.Child
              as={Fragment}
              enter="transform transition duration-300"
              enterFrom="translate-x-[-100%]"     // LEFT → CENTER
              enterTo="translate-x-0"

              leave="transform transition duration-300"
              leaveFrom="translate-x-0"
              leaveTo="translate-x-[-100%]"       // CENTER → LEFT (exit)
            >
              <DialogPanel
                className={cn(
                  "w-full max-w-none h-full bg-white lg:max-w-2xl lg:h-auto lg:rounded-2xl border",
                  dialogBoxStyle,
                )}
              >
                {/* Header */}
                <div className="flex items-center justify-between p-4 border-b border-black/20">
                  {title && <DialogTitle className={cn("font-bold", titleStyle)}>{title}</DialogTitle>}
                  {showCloseIcon && (
                    <span onClick={() => setIsOpen(false)} className="inline-block size-5">
                      <CustomImage
                        imageSrc="/images/icon/close.png"
                        width={1000}
                        height={1000}
                        className="responsive-image-contain"
                      />
                    </span>
                  )}
                </div>

                {description && (
                  <Description className="px-4 mt-4">{description}</Description>
                )}

                <div className={cn("p-4", dialogBodyStyle)}>{children}</div>
              </DialogPanel>
            </Transition.Child>
          </div>
        </Dialog>
      </Transition>
    </>
  )
}

export default DialogBox
